parameters.jsCode:
const text = $json.output?.[0]?.content?.find(item => item.type === 'output_text')?.text ?? $json.text ?? $json.response;
if (!text || !String(text).trim()) throw new Error('AI recommendation text not found');
const weekly = $('Load Weekly Summary').first().json;
return { json: { report_type: 'WEEKLY_OPTIMIZATION', room: weekly.room ?? 'A101', period_start: weekly.periodStart, period_end: weekly.periodEnd, summary: { totalIncidents: weekly.totalIncidents, incidentsByType: weekly.incidentsByType, devicesWithIssues: weekly.devicesWithIssues, source: 'AI' }, recommendation: String(text).trim() } };
